import type { Locale } from "@/i18n/config";
import commons from "../../../public/images/rituals/commons.json";

// ─────────────────────────────────────────────────────────
//  Pictures for the rites, where a good one exists.
//
//  Generated by scripts/images/fetch-commons.mjs, which asks the
//  Commons API for each file's real licence and author and refuses
//  anything not freely licensed.
//
//  **A rite with no picture is a valid state, and the commonest one
//  here.** The festivals could all be illustrated because a festival
//  is a public thing somebody photographed. A rite mostly is not:
//  nobody publishes a photograph of a jātakarma, and the few
//  photographs of a śrāddha that exist are of somebody's grief.
//  Where there is no picture the page shows the rite's name in the
//  reader's own script instead — the same fallback a temple with no
//  free photograph already uses.
//
//  **Alt text says what is in the frame**, not what the rite means,
//  and an id with no alt entry is treated as having no picture at
//  all. A photograph with no description is not an improvement on
//  none.
//
//  **Look at the picture before shipping it.** The festivals shipped
//  a museum exhibit label and a boy with a water pistol by filtering
//  on licence, size and filename and never opening the results.
//
//  Ids are ritual slugs, plus `g-<group>` for the plate at the head
//  of each group on the section's front page.
// ─────────────────────────────────────────────────────────

export interface RitualImage {
  src: string;
  width: number;
  height: number;
  credit: string;
  sourceUrl: string;
  alt: Record<Locale, string>;
  /** Which part of the frame a 4:3 or 16:9 crop must keep. */
  position?: string;
}

