/**
 * Where a crop must hold, for the frames that are not centred. The
 * card is square and the hero is a wide band, so a tall photograph
 * loses a third of itself in each and has to say which third.
 */
const POSITION: Record<string, string> = {
  "g-vrata": "56% 34%", // the crescent sits high and right of centre
  "g-yajna": "50% 46%", // a portrait frame; the kunda is below the middle
  vivaha: "50% 56%", // the fire, not the dark ceiling above it
  antyeshti: "50% 44%",
};

type Entry = { src: string; width: number; height: number; credit: string; sourceUrl: string };
const FROM_COMMONS = commons as Record<string, Entry>;

const IMAGES: Record<string, RitualImage> = {};
for (const [id, entry] of Object.entries(FROM_COMMONS)) {
  const alt = ALT[id];
  if (!alt) continue;
  IMAGES[id] = { ...entry, alt, position: POSITION[id] ?? "50% 50%" };
}

export function ritualImage(slug: string): RitualImage | undefined {
  return IMAGES[slug];
}

export function ritualGroupImage(group: string): RitualImage | undefined {
  return IMAGES[`g-${group}`];
}

export function allRitualImages(): [string, RitualImage][] {
  return Object.entries(IMAGES);
}
